def trinkgeld_und_gesamt(rechnung, prozent):
    betrag = float(rechnung)
    anteil = float(prozent)
    trinkgeld = round(betrag * anteil / 100, 2)
    gesamt = round(betrag + trinkgeld, 2)
    return (trinkgeld, gesamt)

def rechne(a, b, operator):
    if b == 0 and (operator == "/" or operator == "//" or operator == "%"):
        return None
    if operator == "+":
        return a + b
    elif operator == "-":
        return a - b
    elif operator == "*":
        return a * b
    elif operator == "/":
        return a / b
    elif operator == "//":
        return a // b
    elif operator == "%":
        return a % b
    elif operator == "**":
        return a ** b
    else:
        return None
